sp_instance_ais.css:
/* Nadpis – ponecháme pôvodný štýl, len zarovnanie vľavo */
#homepage-search .sp-search-heading {
  text-align: left !important;
  padding-left: 20px;
  font-size: 3rem !important;       /* veľký nadpis */
  font-weight: 700 !important;      /* tučné písmo */
  color: #FFFFFF !important; 
  margin-bottom: 1px !important; /* zníži medzeru pod nadpisom */
}

/* Short description – zväčšené a polotučné */
#homepage-search .sp-tagline-color {
  text-align: left !important;
  padding-left: 20px;
  font-size: 2.1rem;    /* väčšie než bežný text */
  font-weight: 600;     /* polotučné písmo */
  color: #FFFFFF !important; 
  margin-top: 0px !important;     /* zníži medzeru nad short description */
}


/*.sp-search-heading,
.sp-search-description {
